?>
<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><?php include('includes/page-title.php'); ?><meta name="viewport" content="width=device-width, initial-scale=1.0"><link href="<?= base_url(); ?>assets/css/bootstrap.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/icons.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/app.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/libs/datatables/dataTables.bootstrap4.min.css" rel="stylesheet"><style>body{background:#f4f7fb}.submissions-hero{margin:20px 0 24px;padding:30px;border-radius:18px;color:#fff;background:linear-gradient(135deg,#272b8c,#565de8)}.submissions-hero h2{color:#fff;margin:8px 0 0}.submission-table td{vertical-align:middle}.status-select{min-width:150px}.attachment-link{display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:50%;color:#277849;background:#e0f5e8}.pending-status{color:#9a5c20;font-weight:700}.submission-notes{display:block;margin-top:6px;color:#79839a;font-size:.82rem;white-space:pre-line}</style></head><body><div id="wrapper"><?php include('includes/top-bar.php'); ?><?php include('includes/sidebar.php'); ?><div class="content-page"><div class="content"><main class="container-fluid"><section class="submissions-hero"><a class="btn btn-sm btn-light" href="<?= base_url(); ?>Page/pbei_school_submissions"><i class="mdi mdi-arrow-left"></i> Back to Schools Submissions</a><h2><?= $esc($schoolName); ?></h2></section><?php if ($this->session->flashdata('success')): ?><div class="alert alert-success alert-dismissible fade show" role="alert"><?= $esc($this->session->flashdata('success')); ?><button type="button" class="close" data-dismiss="alert">&times;</button></div><?php endif; ?><section class="card"><div class="card-body"><div class="table-responsive"><table id="submissionDetailsTable" class="table table-hover submission-table w-100"><thead><tr><th>Mandatory Documentary Requirements</th><th>Status of Submission</th><th>Remarks</th><th>Save</th></tr></thead><tbody><?php foreach ($submissions as $submission): ?><?php $isSubmitted = !empty($submission->id); $status = $submission->submission_status === 'Validated' ? 'Validated' : 'For Validation'; ?><tr><td><strong><?= (int) $submission->sort_order; ?>. <?= $esc($submission->requirement); ?></strong><?php if ($isSubmitted && trim((string) $submission->notes) !== ''): ?><span class="submission-notes"><strong>School notes:</strong> <?= $esc($submission->notes); ?></span><?php endif; ?></td><td><?php if ($isSubmitted): ?><div class="d-flex align-items-center"><select class="form-control form-control-sm status-select" name="submission_status" form="submissionForm<?= (int) $submission->id; ?>"><option value="For Validation" <?= $status === 'For Validation' ? 'selected' : ''; ?>>For Validation</option><option value="Validated" <?= $status === 'Validated' ? 'selected' : ''; ?>>Validated</option></select><?php if (trim((string) $submission->stored_name) !== ''): ?><a class="attachment-link ml-2" target="_blank" rel="noopener" title="View attachment" aria-label="View attachment" href="<?= base_url(); ?>upload/pbei_requirement_submissions/<?= rawurlencode(basename((string) $submission->stored_name)); ?>"><i class="mdi mdi-eye-outline font-18"></i></a><?php endif; ?></div><?php else: ?><span class="pending-status"><i class="mdi mdi-clock-outline"></i> Not Submitted</span><?php endif; ?></td><td><?php if ($isSubmitted): ?><textarea class="form-control form-control-sm" name="division_remarks" rows="2" form="submissionForm<?= (int) $submission->id; ?>" aria-label="Remarks for <?= $esc($submission->requirement); ?>"><?= $esc($submission->division_remarks); ?></textarea><?php else: ?>—<?php endif; ?></td><td><?php if ($isSubmitted): ?><form id="submissionForm<?= (int) $submission->id; ?>" method="post" action="<?= base_url(); ?>Page/pbei_school_submission_update"><input type="hidden" name="submission_id" value="<?= (int) $submission->id; ?>"><input type="hidden" name="return_school_id" value="<?= $esc($submission->school_id ?: $this->input->get('school_id', TRUE)); ?>"><button class="btn btn-sm btn-primary" type="submit"><i class="mdi mdi-content-save-outline"></i> Save</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></section></main></div><?php include('includes/footer.php'); ?></div></div><script src="<?= base_url(); ?>assets/js/vendor.min.js"></script><script src="<?= base_url(); ?>assets/js/app.min.js"></script><script src="<?= base_url(); ?>assets/libs/datatables/jquery.dataTables.min.js"></script><script src="<?= base_url(); ?>assets/libs/datatables/dataTables.bootstrap4.min.js"></script><script>$(function(){$('#submissionDetailsTable').DataTable({pageLength:25,order:[[0,'asc']]});});</script></body></html>
